        if isinstance(r, (list, tuple)) and len(r) >= 2:
            return int(r[0]), int(r[1])
        if isinstance(r, dict):
            if "x" in r and "y" in r:
                return int(r["x"]), int(r["y"])
            if "position" in r:
                p = r["position"]
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    return int(p[0]), int(p[1])
